package processgraph

import (
	"slices"
	"strconv"
	"strings"
)

var requirementEdgeKinds = []string{"contains", "copies", "derives", "refines", "traces"}

func RequirementEdgeKinds() []string { return slices.Clone(requirementEdgeKinds) }

// Requirement endpoints are numbered sources in the current batch. Card
// labels are taken from their quotes and never generated by the model.
func groundRequirementGraph(draft *Draft, suggestion Suggestion, req Request) {
	sources := req.Sources[:suggestion.UsedSources]
	nodes := make(map[string]bool)
	edges := make(map[[3]string]bool)
	for _, edge := range suggestion.Edges {
		a, e1 := strconv.Atoi(edge.From)
		b, e2 := strconv.Atoi(edge.To)
		key := [3]string{edge.From, edge.To, edge.Kind}
		if e1 != nil || e2 != nil || a < 1 || b < 1 || a > len(sources) || b > len(sources) ||
			sources[a-1].ID == sources[b-1].ID || edges[key] || !slices.Contains(requirementEdgeKinds, edge.Kind) {
			continue
		}
		if edge.Kind == "copies" && strings.TrimSpace(sources[a-1].Text) != strings.TrimSpace(sources[b-1].Text) {
			continue
		}
		evidence := groundedEvidence(edge.Evidence, sources, req.Anchor.Name)
		var from, to Evidence
		for _, item := range evidence {
			switch item.RequirementID {
			case sources[a-1].ID:
				from = item
			case sources[b-1].ID:
				to = item
			}
		}
		if from.RequirementID == "" || to.RequirementID == "" {
			continue
		}
		edges[key] = true
		for _, endpoint := range []struct {
			id       string
			citation Evidence
		}{{edge.From, from}, {edge.To, to}} {
			if nodes[endpoint.id] {
				continue
			}
			nodes[endpoint.id] = true
			draft.Nodes = append(draft.Nodes, Node{
				ID: endpoint.id, Kind: "requirement", Label: requirementCardLabel(endpoint.citation.Quote),
				RequirementID: endpoint.citation.RequirementID, Version: endpoint.citation.Version,
			})
		}
		draft.Edges = append(draft.Edges, Edge{From: edge.From, To: edge.To, Kind: edge.Kind, Evidence: []Evidence{from, to}})
	}
}

func requirementCardLabel(quote string) string {
	label := []rune(strings.Join(strings.Fields(quote), " "))
	if len(label) > MaxLabel {
		return strings.TrimSpace(string(label[:MaxLabel-1])) + "…"
	}
	return string(label)
}
